function dump(n, depth) {
  if (depth > 4) return null;
  return {
    id: n.id, name: n.name, type: n.type,
    w: Math.round(n.width), h: Math.round(n.height),
    chars: n.type === 'TEXT' ? n.characters : undefined,
    fills: (n.fills && n.fills !== figma.mixed) ? n.fills.map(f => ({type: f.type, color: f.color, opacity: f.opacity})) : undefined,
    children: n.children ? n.children.map(c => dump(c, depth+1)) : undefined
  };
}
