function txt(str,size,style,color){const t=figma.createText();t.fontName={family:'Inter',style};t.characters=str;t.fontSize=size;t.fills=[solid(color)];return t;}
async function photoBox(id,w,h,r=0){
  const c=await figma.getNodeByIdAsync(id);
  const f=figma.createFrame();f.name=c.name;f.resize(w,h);f.clipsContent=true;f.fills=[solid({r:0.9,g:0.88,b:0.91})];
  if(r)f.cornerRadius=r;
  const i=c.createInstance();const s=Math.max(w/c.width,h/c.height);
  i.resize(c.width*s,c.height*s);f.appendChild(i);i.x=(w-i.width)/2;i.y=(h-i.height)/2;return f;
}
async function iconInst(id,size,color){
  const c=await figma.getNodeByIdAsync(id);const i=c.createInstance();i.resize(size,size);
  if(color){i.findAll(n=>['VECTOR','BOOLEAN_OPERATION','ELLIPSE','RECTANGLE','STAR','POLYGON','LINE'].includes(n.type)).forEach(v=>{v.fills=[solid(color)];v.strokes=[];});}
  return i;
}

