const comps=['5:26','5:23','5:70','5:29','5:51','5:58','5:54','5:77','5:63','5:67','5:33','5:48','5:45','5:42','5:17','5:20','5:36','5:39','5:81','5:85','5:88','5:91','5:97','5:101','5:105'];
