for(const frame of page.children){
  if(frame.type!=='FRAME'||frame.name==='Meet — Components')continue;
  const insts=frame.findAll(n=>n.type==='INSTANCE');
  for(const inst of insts){
    const mc=await inst.getMainComponentAsync();
    if(!mc)continue;
    if(!comps.includes(mc.id))continue;
    const isStroke=strokeBased.has(mc.id);
    const vecs=inst.findAll(n=>n.type==='VECTOR');
    for(const v of vecs){
      const cur=(v.fills&&v.fills[0]&&v.fills[0].color)?v.fills[0].color:{r:0.10,g:0.086,b:0.11};
      const op=(v.fills&&v.fills[0]&&v.fills[0].opacity!==undefined)?v.fills[0].opacity:1;
      if(isStroke){v.strokes=[solid(cur,op)];v.fills=[];}
      else{v.fills=[solid(cur,op)];v.strokes=[];}
      fixed++;
    }
  }
}
return {fixed, strokeIcons:[...strokeBased].length};

