const lib=await figma.getNodeByIdAsync('9:2');
const comps=lib.findAll(n=>n.type==='COMPONENT');
// find stroke-based source icon components
const iconIds=['5:26','5:23','5:70','5:29','5:51','5:58','5:54','5:77','5:63','5:67','5:33','5:48','5:45','5:42','5:17','5:20','5:36','5:39','5:81','5:85','5:88','5:91','5:97','5:101','5:105','5:10','5:14'];
const strokeIds=new Set();
for(const id of iconIds){const c=await figma.getNodeByIdAsync(id);const vs=c.findAll(n=>n.type==='VECTOR');if(vs.length&&vs.every(v=>(v.strokes||[]).length>0))strokeIds.add(id);}
let fixed=0;
for(const comp of comps){
  const insts=comp.findAll(n=>n.type==='INSTANCE');
  for(const inst of insts){
    const mc=await inst.getMainComponentAsync();
    if(!mc||!iconIds.includes(mc.id))continue;
    const isStroke=strokeIds.has(mc.id);
    for(const v of inst.findAll(n=>n.type==='VECTOR')){
      const cur=(v.fills&&v.fills[0]&&v.fills[0].color)?v.fills[0].color:{r:0.10,g:0.086,b:0.11};
      const op=(v.fills&&v.fills[0]&&v.fills[0].opacity!==undefined)?v.fills[0].opacity:1;
      if(isStroke){v.strokes=[solid(cur,op)];v.fills=[];}else{v.fills=[solid(cur,op)];v.strokes=[];}
      fixed++;
    }
  }
}
// also fix overlay tab bar inactive tint already handled via opacity
return {fixed};

